<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { CircleDollarSign, Plus, RotateCcw, X } from 'lucide-vue-next'
import SectionPanel from '../components/SectionPanel.vue'
import StatusBadge from '../components/StatusBadge.vue'
import WorkspaceStickyStack from '../components/WorkspaceStickyStack.vue'
import JalaliDatePicker from '../components/JalaliDatePicker.vue'
import { loansApi, type LoanPaymentRecord, type LoanRecord } from '../api/loans'
import { accountingApi, type FinancialAccountRecord } from '../api/accounting'
import { formatMoney, type CurrencyUnit } from '../utils/currency'
import { currentCanonicalDate, formatDateTime } from '../utils/date'
const props=defineProps<{currencyUnit:CurrencyUnit}>();const emit=defineEmits<{notify:[string]}>();const rows=ref<LoanRecord[]>([]);const accounts=ref<FinancialAccountRecord[]>([]);const payments=ref<LoanPaymentRecord[]>([]);const selectedId=ref<string|null>(null);const tab=ref('Active');const error=ref('');const createMode=ref(false)
const form=ref({direction:'payable',counterpartyName:'',principalRial:'0',interestFeeRial:'0',startDate:currentCanonicalDate(),endDate:'',financialAccountId:'',installmentCount:'1',notes:''});const pay=ref({principalRial:'0',interestRial:'0',financialAccountId:'',installmentId:''});const selected=computed(()=>rows.value.find(v=>v.id===selectedId.value)??null);const filtered=computed(()=>rows.value.filter(v=>tab.value==='All'||(tab.value==='Payable'&&v.direction==='payable')||(tab.value==='Receivable'&&v.direction==='receivable')||(tab.value==='Closed'&&v.status==='Closed')||(tab.value==='Overdue'&&v.overdueRial>0)||(tab.value==='Active'&&v.status==='Active'&&v.overdueRial===0)))
onMounted(async()=>{try{accounts.value=await accountingApi.financialAccounts();await load()}catch(e){error.value=String(e)}});async function load(){rows.value=await loansApi.list();if(!selectedId.value&&rows.value[0])select(rows.value[0])}async function select(v:LoanRecord){selectedId.value=v.id;createMode.value=false;try{payments.value=await loansApi.payments(v.id)}catch(e){error.value=String(e)}}
function begin(){createMode.value=true;selectedId.value=null;form.value={direction:'payable',counterpartyName:'',principalRial:'0',interestFeeRial:'0',startDate:currentCanonicalDate(),endDate:'',financialAccountId:accounts.value[0]?.id??'',installmentCount:'1',notes:''}}
async function create(){const principal=Number(form.value.principalRial.replaceAll(',',''));const interest=Number(form.value.interestFeeRial.replaceAll(',',''));if(!form.value.counterpartyName||!principal||!form.value.financialAccountId){error.value='Counterparty, account, and positive principal are required.';return}try{const v=await loansApi.create({...form.value,principalRial:principal,interestFeeRial:interest,installmentCount:Number(form.value.installmentCount)});rows.value=[v,...rows.value];await select(v);emit('notify','Loan opened with a balanced journal entry.')}catch(e){error.value=String(e)}}
async function recordPayment(){if(!selected.value)return;const principal=Number(pay.value.principalRial.replaceAll(',',''));const interest=Number(pay.value.interestRial.replaceAll(',',''));if(!principal&&!interest||!pay.value.financialAccountId||!pay.value.installmentId){error.value='Select an installment, account, and payment amount.';return}try{await loansApi.createPayment({loanId:selected.value.id,financialAccountId:pay.value.financialAccountId,paidAt:currentCanonicalDate(),amountRial:principal+interest,principalRial:principal,interestRial:interest,allocations:[{installmentId:pay.value.installmentId,principalRial:principal,interestRial:interest}]});await load();const v=rows.value.find(x=>x.id===selected.value!.id);if(v)await select(v);pay.value={...pay.value,principalRial:'0',interestRial:'0'};emit('notify','Loan payment posted and allocated.') }catch(e){error.value=String(e)}}
async function reversePayment(v:LoanPaymentRecord){try{await loansApi.reversePayment(v.id);if(selected.value)await select(selected.value);emit('notify','Payment reversed with a compensating entry.')}catch(e){error.value=String(e)}}function tone(s:string){return s==='Closed'?'green':s==='Cancelled'?'red':s==='Active'?'blue':'amber'}function date(v:string){try{return formatDateTime(v)}catch{return '—'}}
</script>
<template><div class="loans-view"><WorkspaceStickyStack><header class="workspace-heading"><div><p class="eyebrow">Finance / financing</p><h1>Loans</h1><p class="heading-description">Payable and receivable loans with persisted schedules, derived overdue balances, and reversible payments.</p></div><button class="button button-primary" @click="begin"><Plus :size="16"/> New loan</button></header><section class="orders-filter-bar panel"><div class="workspace-tabs"><button v-for="value in ['Active','Payable','Receivable','Overdue','Closed','All']" :key="value" :class="{'is-active':tab===value}" @click="tab=value">{{value}}</button></div><span class="filter-result">{{filtered.length}} loans</span></section></WorkspaceStickyStack><div v-if="error" class="form-error" role="alert">{{error}} <button class="icon-button" @click="error=''" aria-label="Dismiss"><X :size="14"/></button></div><section class="loans-layout"><SectionPanel title="Loan register" subtitle="Principal, interest, remaining, and overdue values come from posted allocations."><div v-if="filtered.length" class="table-wrap"><table class="data-table"><thead><tr><th>Loan</th><th>Counterparty</th><th>Type</th><th>Remaining</th><th>Overdue</th><th>Status</th></tr></thead><tbody><tr v-for="v in filtered" :key="v.id" :class="{'is-selected':selectedId===v.id}" @click="select(v)"><td><span class="table-primary">{{v.loanNumber}}</span><span class="table-secondary">{{date(v.startDate)}}</span></td><td>{{v.counterpartyName}}</td><td>{{v.direction==='payable'?'Payable':'Receivable'}}</td><td>{{formatMoney(v.remainingPrincipalRial+v.remainingInterestRial,props.currencyUnit)}}</td><td>{{formatMoney(v.overdueRial,props.currencyUnit)}}</td><td><StatusBadge :label="v.status" :tone="tone(v.status)"/></td></tr></tbody></table></div><div v-else class="workspace-state"><CircleDollarSign :size="22"/><p>No loans in this view.</p></div></SectionPanel><SectionPanel v-if="createMode" title="New loan" subtitle="Opening the loan posts principal to cash/bank and the loan balance."><form class="loan-form" @submit.prevent="create"><div class="loan-form-grid"><label class="form-field"><span>Type</span><select v-model="form.direction"><option value="payable">Payable / borrowed</option><option value="receivable">Receivable / lent</option></select></label><label class="form-field"><span>Counterparty</span><input v-model="form.counterpartyName" required/></label><label class="form-field"><span>Principal (Rial)</span><input v-model="form.principalRial" inputmode="numeric"/></label><label class="form-field"><span>Interest / fees (Rial)</span><input v-model="form.interestFeeRial" inputmode="numeric"/></label><label class="form-field"><span>Start date</span><JalaliDatePicker v-model="form.startDate"/></label><label class="form-field"><span>Installments</span><input v-model="form.installmentCount" type="number" min="1"/></label><label class="form-field"><span>Cash / bank account</span><select v-model="form.financialAccountId"><option v-for="a in accounts" :key="a.id" :value="a.id">{{a.name}}</option></select></label></div><label class="form-field"><span>Notes</span><textarea v-model="form.notes" rows="3"/></label><div class="inspector-actions"><button class="button button-secondary" type="button" @click="createMode=false">Cancel</button><button class="button button-primary">Open loan</button></div></form></SectionPanel><SectionPanel v-else-if="selected" title="Loan inspector" :subtitle="`${selected.loanNumber} · ${selected.counterpartyName}`"><div class="loan-inspector"><div class="inspector-heading"><div class="material-inspector-icon"><CircleDollarSign :size="19"/></div><div><h3>{{selected.direction==='payable'?'Payable loan':'Receivable loan'}}</h3><p>{{date(selected.startDate)}}<template v-if="selected.endDate"> → {{date(selected.endDate)}}</template></p></div></div><StatusBadge :label="selected.status" :tone="tone(selected.status)"/><dl class="purchase-totals"><div><dt>Principal remaining</dt><dd>{{formatMoney(selected.remainingPrincipalRial,props.currencyUnit)}}</dd></div><div><dt>Interest remaining</dt><dd>{{formatMoney(selected.remainingInterestRial,props.currencyUnit)}}</dd></div><div><dt>Overdue</dt><dd>{{formatMoney(selected.overdueRial,props.currencyUnit)}}</dd></div></dl><div class="loan-schedule"><h3>Installment schedule</h3><div v-for="i in selected.installments" :key="i.id" class="accounting-row"><span><strong>#{{i.position+1}} · {{date(i.dueDate)}}</strong><small>{{formatMoney(i.paidRial,props.currencyUnit)}} paid · {{formatMoney(i.remainingRial,props.currencyUnit)}} remaining</small></span><StatusBadge :label="i.status" :tone="i.status==='Paid'?'green':i.status==='Overdue'?'red':'amber'"/></div></div><div class="loan-payment-form"><h3>Record payment</h3><div class="loan-form-grid"><select v-model="pay.installmentId"><option value="">Installment</option><option v-for="i in selected.installments.filter(x=>x.remainingRial>0)" :key="i.id" :value="i.id">#{{i.position+1}} · {{formatMoney(i.remainingRial,props.currencyUnit)}}</option></select><select v-model="pay.financialAccountId"><option value="">Cash / bank account</option><option v-for="a in accounts" :key="a.id" :value="a.id">{{a.name}}</option></select><input v-model="pay.principalRial" placeholder="Principal (Rial)" inputmode="numeric"/><input v-model="pay.interestRial" placeholder="Interest (Rial)" inputmode="numeric"/></div><button class="button button-secondary" @click="recordPayment">Record payment</button></div><div class="loan-payments"><h3>Payment history</h3><div v-for="p in payments" :key="p.id" class="accounting-row"><span><strong>{{formatMoney(p.amountRial,props.currencyUnit)}}</strong><small>{{date(p.paidAt)}} · {{p.status}}</small></span><button v-if="p.status==='Posted'" class="text-button" @click="reversePayment(p)"><RotateCcw :size="14"/> Reverse</button></div><div v-if="!payments.length" class="workspace-state">No payments yet.</div></div></div></SectionPanel><SectionPanel v-else title="Loan inspector" subtitle="Select a loan to inspect its schedule."><div class="workspace-state">No loan selected.</div></SectionPanel></section></div></template>
<style scoped>.loans-view{display:grid;gap:16px;min-width:0}.loans-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(320px,480px);gap:16px;align-items:start}.workspace-tabs{display:flex;gap:4px;overflow:auto}.workspace-tabs button{border:0;background:transparent;padding:7px 9px;color:var(--text-muted);white-space:nowrap;border-radius:7px;cursor:pointer}.workspace-tabs button.is-active{background:var(--surface-muted);color:var(--text)}.loan-form,.loan-inspector{display:grid;gap:14px;min-width:0}.loan-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.loan-schedule,.loan-payment-form,.loan-payments{display:grid;gap:9px;border-top:1px solid var(--border);padding-top:14px}.loan-schedule h3,.loan-payment-form h3,.loan-payments h3{font-size:13px;margin:0}@media(max-width:1050px){.loans-layout{grid-template-columns:1fr}}@media(max-width:650px){.loan-form-grid{grid-template-columns:1fr}}
</style>
